// Creates .env.local with fresh local-dev secrets if it does not exist yet.
import { randomBytes } from 'node:crypto';
import { existsSync, writeFileSync } from 'node:fs';

const FILE = '.env.local';
if (existsSync(FILE)) {
  console.log(`${FILE} already exists, leaving it untouched.`);
} else {
  writeFileSync(
    FILE,
    [
      '# Local development only. Generated by scripts/setup-env.mjs — do not commit.',
      '# Frontend (exposed to the browser): only VITE_* values.',
      'VITE_CHAIN=anvil',
      '',
      '# API server (never exposed to the browser)',
      'CHAIN=anvil',
      '# Host the game is served from; SIWE messages for any other domain are rejected.',
      'SIWE_DOMAIN=localhost:5173',
      `SERVER_SIGNER_KEY=0x${randomBytes(32).toString('hex')}`,
      `SESSION_SECRET=${randomBytes(32).toString('hex')}`,
      '',
    ].join('\n'),
  );
  console.log(`Created ${FILE} with fresh local secrets.`);
}
